import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> segments = Arrays.asList(1, 2, 3, 4, 5);
        Set<Integer> lostOnFirstAttempt = new HashSet<>(Arrays.asList(2, 4));

        List<Integer> unreliableResult = unreliableSend(segments, lostOnFirstAttempt);
        System.out.println("UDP style, single attempt, delivered: " + unreliableResult);

        Result reliableResult = reliableSend(segments, lostOnFirstAttempt);
        System.out.println("TCP style, delivered: " + reliableResult.delivered);
        System.out.println("TCP style, total transmissions used: " + reliableResult.totalTransmissions);
    }

    // UDP style: send once, report only whatever actually arrived, no retry at all.
    static List<Integer> unreliableSend(List<Integer> segments, Set<Integer> lostOnFirstAttempt) {
        List<Integer> delivered = new ArrayList<>();
        for (int segment : segments) {
            if (!lostOnFirstAttempt.contains(segment)) {
                delivered.add(segment);
            }
        }
        return delivered;
    }

    static class Result {
        List<Integer> delivered;
        int totalTransmissions;
        Result(List<Integer> delivered, int totalTransmissions) {
            this.delivered = delivered;
            this.totalTransmissions = totalTransmissions;
        }
    }

    // TCP style: keep retransmitting any segment that was not yet acknowledged.
    // In this simulation, anything lost on attempt 1 always succeeds on attempt 2.
    static Result reliableSend(List<Integer> segments, Set<Integer> lostOnFirstAttempt) {
        List<Integer> delivered = new ArrayList<>();
        int totalTransmissions = 0;
        List<Integer> pending = new ArrayList<>(segments);

        totalTransmissions += pending.size();
        List<Integer> needsRetransmit = new ArrayList<>();
        for (int segment : pending) {
            if (lostOnFirstAttempt.contains(segment)) {
                needsRetransmit.add(segment);
            } else {
                delivered.add(segment);
            }
        }

        totalTransmissions += needsRetransmit.size();
        delivered.addAll(needsRetransmit);

        Collections.sort(delivered);
        return new Result(delivered, totalTransmissions);
    }
}

