#include <iostream>
#include <vector>
#include <set>
#include <algorithm>
using namespace std;

// UDP style: send once, report only whatever actually arrived, no retry at all.
vector<int> unreliableSend(const vector<int>& segments, const set<int>& lostOnFirstAttempt) {
    vector<int> delivered;
    for (int segment : segments) {
        if (lostOnFirstAttempt.find(segment) == lostOnFirstAttempt.end()) {
            delivered.push_back(segment);
        }
    }
    return delivered;
}

// TCP style: keep retransmitting any segment that was not yet acknowledged.
// In this simulation, anything lost on attempt 1 always succeeds on attempt 2.
pair<vector<int>, int> reliableSend(const vector<int>& segments, const set<int>& lostOnFirstAttempt) {
    int totalTransmissions = static_cast<int>(segments.size());
    vector<int> delivered;
    vector<int> needsRetransmit;

    for (int segment : segments) {
        if (lostOnFirstAttempt.count(segment)) {
            needsRetransmit.push_back(segment);
        } else {
            delivered.push_back(segment);
        }
    }

    totalTransmissions += static_cast<int>(needsRetransmit.size());
    for (int segment : needsRetransmit) delivered.push_back(segment);
    sort(delivered.begin(), delivered.end());

    return {delivered, totalTransmissions};
}

void printVector(const string& label, const vector<int>& values) {
    cout << label << ": [";
    for (size_t i = 0; i < values.size(); i++) {
        cout << values[i];
        if (i + 1 < values.size()) cout << ", ";
    }
    cout << "]" << endl;
}

int main() {
    vector<int> segments = {1, 2, 3, 4, 5};
    set<int> lostOnFirstAttempt = {2, 4};

    vector<int> unreliableResult = unreliableSend(segments, lostOnFirstAttempt);
    printVector("UDP style, single attempt, delivered", unreliableResult);

    auto reliableResult = reliableSend(segments, lostOnFirstAttempt);
    printVector("TCP style, delivered", reliableResult.first);
    cout << "TCP style, total transmissions used: " << reliableResult.second << endl;

    return 0;
}
